      "symbol": "string",
      "price": "number",
      "amount": "number"
    }
  },
  "remove_stock_from_watchlist": {
    "description": "Remove a stock from the watchlist.",
    "parameters": {
      "symbol": "string"
    }
  },
  "trading_get_login_status": {
    "description": "Get the login status."
  },
  "trading_login": {
    "description": "Handle user login.",
    "parameters": {
      "username": "string",
      "password": "string"
    }
  },
  "trading_logout": {
    "description": "Handle user logout for trading system."
  },
  "withdraw_funds": {
    "description": "Withdraw funds from the account balance.",
    "parameters": {
      "amount": "number"
    }
  },
  "get_order_details": {
    "description": "Get the details of an order.",
    "parameters": {
      "order_id": "number"
    }
  }
}
